contract InvMutTest {
    C c;
    address[] tos;
    address lastFrom;
    address lastTo;
    uint lastV;
    uint callCount;
    constructor(C _c) { c = _c; }
    function run(address from, address to1, address to2, uint v) public {
        require(to1 != address(0));
        require(to2 != address(0));
        delete tos;
        tos.push(to1);
        tos.push(to2);
        lastFrom = address(0);
        lastTo = address(0);
        lastV = 0;
        callCount = 0;
        bool ok = c.transfer(from, address(this), tos, v);
        assert(ok && callCount == 2 && lastFrom == from && lastV == v && (lastTo == to1 || lastTo == to2));
    }
    fallback() external payable {
        bytes memory data = msg.data;
        bytes4 sel;
        address f;
        address t;
        uint val;
        assembly {
            sel := mload(add(data, 32))
            f := mload(add(data, 36))
            t := mload(add(data, 68))
            val := mload(add(data, 100))
        }
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        if (data.length == 100 && sel == id) {
            lastFrom = f;
            lastTo = t;
            lastV = val;
            callCount = callCount + 1;
        }
    }
    receive() external payable {}
}

