contract InvMutTest {
    C c;
    uint calls;
    address lastFrom;
    address lastTo;
    uint lastV;
    constructor(C _c) { c = _c; }
    function run(address from, address to, uint v) public {
        require(v < 1000);
        address[] memory tos = new address[](1);
        tos[0] = to;
        calls = 0;
        bool ok = c.transfer(from, address(this), tos, v);
        assert(ok && calls == 1 && lastFrom == from && lastTo == to && lastV == v);
    }
    fallback() external payable {
        calls++;
        if (msg.data.length >= 100) {
            bytes memory d = new bytes(msg.data.length);
            for (uint i = 0; i < msg.data.length; i++) {
                d[i] = msg.data[i];
            }
            bytes20 f;
            bytes20 t;
            bytes32 vv;
            for (uint i = 0; i < 20; i++) f |= bytes20(d[16 + i] & 0xff) >> (8 * (19 - i));
            for (uint i = 0; i < 20; i++) t |= bytes20(d[48 + i] & 0xff) >> (8 * (19 - i));
            for (uint i = 0; i < 32; i++) vv |= bytes32(d[68 + i] & 0xff) >> (8 * (31 - i));
            lastFrom = address(f);
            lastTo = address(t);
            lastV = uint(vv);
        }
    }
}

