        bool reverted;
        bool ret;
        if (tos.length == 0) {
            try c.transfer(from, address(this), tos, v) returns (bool r) {
                reverted = false;
                ret = r;
            } catch {
                reverted = true;
                ret = false;
            }
        } else {
            ret = c.transfer(from, address(this), tos, v);
            reverted = false;
        }
        assert((tos.length == 0 && reverted) || (tos.length > 0 && !reverted && ret == true));
    }
    fallback(bytes calldata) external payable returns (bytes memory) {
        return abi.encode(true);
    }
    receive() external payable {}
}

